/// <summary>Scaling mode for per-matrix scaling. See documentation for layout information. (<c>cublasLtMatmulMatrixScale_t</c>)</summary>
public enum cublasLtMatmulMatrixScale_t : int
{
    /// <summary>Scaling factors are single precision scalars applied to the whole tensor.</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_SCALAR_32F = 0,
    /// <summary>Scaling factors are tensors that contain a dedicated scaling factor stored as an 8-bit CUDA_R_8F_UE4M3 value for each 16-element block in the innermost dimension of the corresponding data tensor.</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_VEC16_UE4M3 = 1,
    /// <summary>Same as above, except that scaling factor tensor elements have type CUDA_R_8F_UE8M0 and the block size is 32 elements.</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_VEC32_UE8M0 = 2,
    /// <summary>Scaling factors are vectors of CUDA_R_32F values. This mode is only applicable to matrices A and B, in which case the vectors are expected to have M and N elements respectively, and each (i, j)-th element of product of A and B is multiplied by i-th element of A scale and j-th element of B scale.</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_OUTER_VEC_32F = 3,
    /// <summary>Scaling factors are tensors that contain a dedicated CUDA_R_32F scaling factor for each 128-element block in the innermost dimension of the corresponding data tensor.</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_VEC128_32F = 4,
    /// <summary>Scaling factors are tensors that contain a dedicated CUDA_R_32F scaling factor for each 128x128-element block in the the corresponding data tensor.</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_BLK128x128_32F = 5,
    /// <summary>Experimental: Scaling factors are single precision scalars applied to the whole tensor. Each batch has its own scaling factor.</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_PER_BATCH_SCALAR_32F = 6,
    /// <summary>Scaling factors are tensors of packed CUDA_R_8U (UE8M0) values in a simple column-major layout. Four E8M0 exponents covering consecutive 128-element K-blocks are packed into one uint32. The uint32 elements are stored M-major (for A) or N-major (for B) with shape round_up(M,4) x ceil(K/512) (A) or round_up(N,4) x ceil(K/512) (B).</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_VEC128_MN_K4_UE8M0 = 12,
    /// <summary>Same as VEC128_MN_K4_UE8M0 but with 32-element K-block granularity. Four E8M0 exponents covering consecutive 32-element K-blocks are packed into one uint32. Shape is round_up(M,4) x ceil(K/128) (A) or round_up(N,4) x ceil(K/128) (B).</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_VEC32_MN_K4_UE8M0 = 13,
    /// <summary>Same as VEC128_MN_K4_UE8M0 but with 32-element K-block granularity. Four E8M0 exponents covering consecutive 32-element K-blocks are packed into one uint32. Shape is round_up(M,4) x ceil(K/128) (A) or round_up(N,4) x ceil(K/128) (B).</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_END = 14,
    /// <summary>Reserved enumerator, do not use</summary>
    CUBLASLT_MATMUL_MATRIX_SCALE_RESERVED = 127,
}

