/// <summary>Capabilities Attributes that can be retrieved from an initialized Algo structure (<c>cublasLtMatmulAlgoCapAttributes_t</c>)</summary>
public enum cublasLtMatmulAlgoCapAttributes_t : int
{
    /// <summary>support for split K, see CUBLASLT_ALGO_CONFIG_SPLITK_NUM</summary>
    CUBLASLT_ALGO_CAP_SPLITK_SUPPORT = 0,
    /// <summary>reduction scheme mask, see cublasLtReductionScheme_t; shows supported reduction schemes, if reduction scheme is not masked out it is supported.</summary>
    CUBLASLT_ALGO_CAP_REDUCTION_SCHEME_MASK = 1,
    /// <summary>support for cta swizzling, see CUBLASLT_ALGO_CONFIG_CTA_SWIZZLING</summary>
    CUBLASLT_ALGO_CAP_CTA_SWIZZLING_SUPPORT = 2,
    /// <summary>support strided batch</summary>
    CUBLASLT_ALGO_CAP_STRIDED_BATCH_SUPPORT = 3,
    /// <summary>support results out of place (D != C in D = alpha.A.B + beta.C)</summary>
    CUBLASLT_ALGO_CAP_OUT_OF_PLACE_RESULT_SUPPORT = 4,
    /// <summary>syrk/herk support (on top of regular gemm)</summary>
    CUBLASLT_ALGO_CAP_UPLO_SUPPORT = 5,
    /// <summary>tile ids possible to use, see cublasLtMatmulTile_t; if no tile ids are supported use CUBLASLT_MATMUL_TILE_UNDEFINED</summary>
    CUBLASLT_ALGO_CAP_TILE_IDS = 6,
    /// <summary>custom option range is from 0 to CUBLASLT_ALGO_CAP_CUSTOM_OPTION_MAX (inclusive), see CUBLASLT_ALGO_CONFIG_CUSTOM_OPTION</summary>
    CUBLASLT_ALGO_CAP_CUSTOM_OPTION_MAX = 7,
    /// <summary>describes if the algorithm supports custom (not COL or ROW memory order), see cublasLtOrder_t</summary>
    CUBLASLT_ALGO_CAP_CUSTOM_MEMORY_ORDER = 10,
    /// <summary>bitmask enumerating pointer modes algorithm supports</summary>
    CUBLASLT_ALGO_CAP_POINTER_MODE_MASK = 11,
    /// <summary>bitmask enumerating kinds of postprocessing algorithm supports in the epilogue</summary>
    CUBLASLT_ALGO_CAP_EPILOGUE_MASK = 12,
    /// <summary>stages ids possible to use, see cublasLtMatmulStages_t; if no stages ids are supported use CUBLASLT_MATMUL_STAGES_UNDEFINED</summary>
    CUBLASLT_ALGO_CAP_STAGES_IDS = 13,
    /// <summary>support for nagative ld for all of the matrices</summary>
    CUBLASLT_ALGO_CAP_LD_NEGATIVE = 14,
    /// <summary>details about algorithm&apos;s implementation that affect it&apos;s numerical behavior</summary>
    CUBLASLT_ALGO_CAP_NUMERICAL_IMPL_FLAGS = 15,
    /// <summary>minimum alignment required for A matrix in bytes (required for buffer pointer, leading dimension, and possibly other strides defined for matrix memory order)</summary>
    CUBLASLT_ALGO_CAP_MIN_ALIGNMENT_A_BYTES = 16,
    /// <summary>minimum alignment required for B matrix in bytes (required for buffer pointer, leading dimension, and possibly other strides defined for matrix memory order)</summary>
    CUBLASLT_ALGO_CAP_MIN_ALIGNMENT_B_BYTES = 17,
    /// <summary>minimum alignment required for C matrix in bytes (required for buffer pointer, leading dimension, and possibly other strides defined for matrix memory order)</summary>
    CUBLASLT_ALGO_CAP_MIN_ALIGNMENT_C_BYTES = 18,
    /// <summary>minimum alignment required for D matrix in bytes (required for buffer pointer, leading dimension, and possibly other strides defined for matrix memory order)</summary>
    CUBLASLT_ALGO_CAP_MIN_ALIGNMENT_D_BYTES = 19,
    /// <summary>support pointer array batch</summary>
    CUBLASLT_ALGO_CAP_POINTER_ARRAY_BATCH_SUPPORT = 21,
    /// <summary>describes if the algorithm supports floating point emulation</summary>
    CUBLASLT_ALGO_CAP_FLOATING_POINT_EMULATION_SUPPORT = 22,
    /// <summary>support pointer array grouped</summary>
    CUBLASLT_ALGO_CAP_POINTER_ARRAY_GROUPED_SUPPORT = 23,
}

/// <summary>Algo Configuration Attributes that can be set according to the Algo capabilities (<c>cublasLtMatmulAlgoConfigAttributes_t</c>)</summary>
public enum cublasLtMatmulAlgoConfigAttributes_t : int
{
    /// <summary>algorithm index, see cublasLtMatmulAlgoGetIds()</summary>
    CUBLASLT_ALGO_CONFIG_ID = 0,
    /// <summary>tile id, see cublasLtMatmulTile_t</summary>
    CUBLASLT_ALGO_CONFIG_TILE_ID = 1,
    /// <summary>Number of K splits. If the number of K splits is greater than one, SPLITK_NUM parts of matrix multiplication will be computed in parallel. The results will be accumulated according to CUBLASLT_ALGO_CONFIG_REDUCTION_SCHEME</summary>
    CUBLASLT_ALGO_CONFIG_SPLITK_NUM = 2,
    /// <summary>reduction scheme, see cublasLtReductionScheme_t</summary>
    CUBLASLT_ALGO_CONFIG_REDUCTION_SCHEME = 3,
    /// <summary>cta swizzling, change mapping from CUDA grid coordinates to parts of the matrices</summary>
    CUBLASLT_ALGO_CONFIG_CTA_SWIZZLING = 4,
    /// <summary>custom option, each algorithm can support some custom options that don&apos;t fit description of the other config attributes, see CUBLASLT_ALGO_CAP_CUSTOM_OPTION_MAX to get accepted range for any specific case</summary>
    CUBLASLT_ALGO_CONFIG_CUSTOM_OPTION = 5,
    /// <summary>stages id, see cublasLtMatmulStages_t</summary>
    CUBLASLT_ALGO_CONFIG_STAGES_ID = 6,
    /// <summary>inner shape id, see cublasLtMatmulInnerShape_t</summary>
    CUBLASLT_ALGO_CONFIG_INNER_SHAPE_ID = 7,
    /// <summary>Thread Block Cluster shape id, see cublasLtClusterShape_t. Defines cluster size to use.</summary>
    CUBLASLT_ALGO_CONFIG_CLUSTER_SHAPE_ID = 8,
}

